import type { MaterialGrade } from '../../../constants/gradeSystem';
import { material_grade_for } from '../../../constants/gradeSystem';
import {
  normalize_warehouse_item_name,
  warehouse_slot_meta,
  type WarehouseTopCategory,
} from '../../../constants/warehouseCatalog';
import type { SquadActionKey } from './squadActionMechanism';

/** 单技能由背包提供的加成上限（总量，含多件累加后截断） */
export const PACK_BONUS_CAP_PER_SKILL = 8;

/** 各材料品级：每装入 1 单位贡献的基础加成点（常见/普通无加成） */
export const PACK_GRADE_POINTS: Record<MaterialGrade, number> = {
  常见: 0,
  普通: 0,
  少有: 1,
  罕见: 2,
  稀世: 3,
};

export type PackSkillBonus = Partial<Record<'狩猎' | '战斗' | '采集' | '后勤', number>>;

type SkillKey = '狩猎' | '战斗' | '采集' | '后勤';

/** 类别×行动 → 加成点分配到哪些技能（值为权重，按点数的比例分配并取整） */
const PACK_SKILL_ROUTES: Record<
  SquadActionKey,
  Partial<Record<WarehouseTopCategory, Partial<Record<string, Partial<Record<SkillKey, number>>>>>>
> = {
  探索: {
    食物: { '*': { 后勤: 1 } },
    材料: {
      原材料: { 采集: 1 },
      加工材料: { 战斗: 1 },
      纤维与皮革: { 后勤: 1 },
      其他: { 采集: 1 },
    },
    燃料: { '*': { 后勤: 1 } },
    医疗: {
      草药原料: { 后勤: 1 },
      成药敷剂: { 后勤: 1 },
    },
    工具与装备: {
      武器: { 战斗: 1 },
      工具: { 后勤: 1 },
      陷阱: { 战斗: 1 },
      织物与日常: { 后勤: 1 },
    },
    珍异储备: { '*': { 后勤: 1 } },
  },
  狩猎: {
    食物: { '*': { 后勤: 1 } },
    材料: {
      加工材料: { 狩猎: 1 },
      纤维与皮革: { 狩猎: 1 },
      原材料: { 战斗: 1 },
    },
    燃料: { '*': { 后勤: 1, 狩猎: 1 } },
    医疗: {
      草药原料: { 后勤: 1 },
      成药敷剂: { 后勤: 1 },
    },
    工具与装备: {
      武器: { 战斗: 1, 狩猎: 1 },
      工具: { 狩猎: 1 },
      陷阱: { 狩猎: 1 },
    },
    珍异储备: { '*': { 狩猎: 1, 战斗: 1 } },
  },
  采集: {
    食物: { '*': { 后勤: 1 } },
    材料: {
      原材料: { 采集: 1 },
      加工材料: { 采集: 1 },
      纤维与皮革: { 后勤: 1 },
      其他: { 采集: 1 },
    },
    燃料: { '*': { 后勤: 1 } },
    医疗: {
      草药原料: { 采集: 1, 后勤: 1 },
      成药敷剂: { 后勤: 1 },
    },
    工具与装备: {
      工具: { 采集: 1 },
      陷阱: { 采集: 1 },
      织物与日常: { 后勤: 1 },
    },
    珍异储备: { '*': { 采集: 1 } },
  },
};

function route_weights(
  mode: SquadActionKey,
  top: WarehouseTopCategory,
  sub: string,
): Partial<Record<SkillKey, number>> {
  const modeRoutes = PACK_SKILL_ROUTES[mode];
  const topRoutes = modeRoutes[top];
  if (!topRoutes) return {};
  return topRoutes[sub] ?? topRoutes['*'] ?? topRoutes.其他 ?? {};
}

/** 将品级点数按类别路由拆成技能加成（单件 qty=1） */
export function pack_bonus_for_item(name: string, mode: SquadActionKey): PackSkillBonus {
  const key = normalize_warehouse_item_name(name);
  const { top, sub } = warehouse_slot_meta(key);
  const points = PACK_GRADE_POINTS[material_grade_for(key)];
  if (points <= 0) return {};

  const weights = route_weights(mode, top, sub);
  const weightSum = Object.values(weights).reduce((s, w) => s + (w ?? 0), 0);
  if (weightSum <= 0) return {};

  const bonus: PackSkillBonus = {};
  let allocated = 0;
  const entries = Object.entries(weights) as [SkillKey, number][];
  entries.forEach(([skill, weight], index) => {
    if (index === entries.length - 1) {
      bonus[skill] = points - allocated;
    } else {
      const share = Math.max(0, Math.round((points * weight) / weightSum));
      bonus[skill] = share;
      allocated += share;
    }
  });
  return bonus;
}

export function pack_weight_for_item(name: string): number {
  const key = normalize_warehouse_item_name(name);
  const { top, sub } = warehouse_slot_meta(key);
  if (top === '工具与装备' && /矛|斧|叉|陷阱|拖板|浮木排/.test(key)) return 2;
  if (top === '燃料' && sub === '主燃料') return 2;
  if (top === '材料' && sub === '原材料' && /坚固木材|石料|普通石料/.test(key)) return 2;
  return 1;
}

export function pack_item_hint(name: string, mode: SquadActionKey): string {
  const key = normalize_warehouse_item_name(name);
  const { top, sub } = warehouse_slot_meta(key);
  const grade = material_grade_for(key);
  const bonus = pack_bonus_for_item(key, mode);
  const bonusText = format_pack_bonus_text(bonus);
  const topLabels: Record<WarehouseTopCategory, string> = {
    食物: '食物',
    材料: '材料',
    燃料: '燃料',
    医疗: '医疗',
    工具与装备: '装备',
    珍异储备: '珍异',
  };
  const cat = `${grade}${topLabels[top]}${sub !== '其他' ? `·${sub}` : ''}`;
  if (bonusText === '无额外加成') {
    return `${cat} · 仅占负重`;
  }
  return `${cat} · ${bonusText}`;
}

export function clamp_pack_skill_bonus(bonus: PackSkillBonus): PackSkillBonus {
  const out: PackSkillBonus = {};
  for (const key of ['狩猎', '战斗', '采集', '后勤'] as const) {
    const v = bonus[key];
    if (v && v > 0) {
      out[key] = Math.min(PACK_BONUS_CAP_PER_SKILL, v);
    }
  }
  return out;
}

export function merge_pack_bonuses(base: PackSkillBonus, add: PackSkillBonus, qty = 1): PackSkillBonus {
  const merged: PackSkillBonus = { ...base };
  for (const key of ['狩猎', '战斗', '采集', '后勤'] as const) {
    const delta = (add[key] ?? 0) * qty;
    if (delta <= 0) continue;
    merged[key] = (merged[key] ?? 0) + delta;
  }
  return clamp_pack_skill_bonus(merged);
}

export function format_pack_bonus_text(bonus: PackSkillBonus): string {
  const parts: string[] = [];
  if (bonus.狩猎) parts.push(`狩猎+${bonus.狩猎}`);
  if (bonus.战斗) parts.push(`战斗+${bonus.战斗}`);
  if (bonus.采集) parts.push(`采集+${bonus.采集}`);
  if (bonus.后勤) parts.push(`后勤+${bonus.后勤}`);
  return parts.length ? parts.join(' ') : '无额外加成';
}

export function pack_category_label(name: string): string {
  const { top, sub } = warehouse_slot_meta(normalize_warehouse_item_name(name));
  const grade = material_grade_for(name);
  return `${grade}·${top}${sub !== '其他' ? `/${sub}` : ''}`;
}
