muted {\n    color: #a88a6d;\n  }\n}\n\n.new-squad-btn {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 8px 14px;\n  font-size: 0.82rem;\n}\n\n.squad-grid {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 14px;\n}\n\n.squad-card {\n  background: #fcf8f0;\n  border: 2px solid #e4d4ba;\n  border-radius: 16px;\n  padding: 16px;\n  display: flex;\n  flex-direction: column;\n  transition: border-color 0.2s;\n\n  &:hover {\n    border-color: #c8955c;\n  }\n}\n\n.squad-main {\n  display: grid;\n  grid-template-columns: 1fr minmax(140px, 200px);\n  gap: 14px;\n  align-items: start;\n  margin-bottom: 12px;\n}\n\n.squad-left {\n  min-width: 0;\n}\n\n.squad-eval {\n  background: #fdfbf7;\n  border: 2px dashed #d4c2a4;\n  border-radius: 12px;\n  padding: 10px 12px;\n}\n\n.eval-title {\n  margin: 0 0 4px;\n  font-size: 0.75rem;\n  font-weight: 900;\n  color: #8c7462;\n}\n\n.eval-cap {\n  font-size: 0.65rem;\n  font-weight: 700;\n  color: #a88a6d;\n}\n\n.eval-formula {\n  margin: 0 0 8px;\n  font-size: 0.6rem;\n  font-weight: 700;\n  color: #a88a6d;\n}\n\n.skill-line {\n  display: grid;\n  grid-template-columns: 36px 1fr auto;\n  gap: 6px;\n  align-items: center;\n  font-size: 0.72rem;\n  font-weight: 700;\n  color: #5c4738;\n  margin-bottom: 4px;\n\n  strong {\n    color: #a8543f;\n    font-size: 0.82rem;\n  }\n}\n\n.skill-tier {\n  font-size: 0.62rem;\n  color: #8c7462;\n}\n\n.action-eval {\n  margin-top: 10px;\n  padding-top: 10px;\n  border-top: 1px dashed #e4d4ba;\n}\n\n.action-mechanism-block {\n  & + & {\n    margin-top: 10px;\n    padding-top: 10px;\n    border-top: 1px dashed #efe4d4;\n  }\n}\n\n.action-focus {\n  margin: 4px 0 6px;\n  font-size: 0.64rem;\n  font-weight: 700;\n  color: #8c7462;\n  line-height: 1.4;\n}\n\n.output-tiers {\n  margin: 0 0 6px;\n  padding: 0;\n  list-style: none;\n\n  li {\n    margin: 0 0 3px;\n    font-size: 0.62rem;\n    font-weight: 700;\n    color: #6b4c3a;\n    line-height: 1.35;\n  }\n}\n\n.tier-tag {\n  di