import { parse_beast_calendar_date, type BeastCalendarDate } from './beastCalendar';

export type SurvivalCountdownTone = 'active' | 'soon' | 'normal';

export type SurvivalCountdown = {
  id: 'invasion' | 'storm' | 'winter';
  label: string;
  text: string;
  tone: SurvivalCountdownTone;
};

const EMPTY_COUNTDOWNS: SurvivalCountdown[] = [
  { id: 'invasion', label: '野兽入侵', text: '—', tone: 'normal' },
  { id: 'storm', label: '夏季雷暴', text: '—', tone: 'normal' },
  { id: 'winter', label: '冬季寒潮', text: '—', tone: 'normal' },
];

function dayIndex(date: BeastCalendarDate): number {
  return Math.floor(Date.UTC(date.year, date.month - 1, date.day) / 86_400_000);
}

function daysBetween(from: BeastCalendarDate, to: BeastCalendarDate): number {
  return dayIndex(to) - dayIndex(from);
}

function lastDayOfMonth(year: number, month: number): number {
  return new Date(year, month, 0).getDate();
}

function isInSeasonWindow(cal: BeastCalendarDate, startMonth: number, startDay: number, duration: number) {
  if (cal.month !== startMonth) {
    return false;
  }
  return cal.day >= startDay && cal.day < startDay + duration;
}

function nextSeasonStart(cal: BeastCalendarDate, startMonth: number, startDay: number): BeastCalendarDate {
  let year = cal.year;
  if (cal.month > startMonth || (cal.month === startMonth && cal.day >= startDay)) {
    year += 1;
  }
  return { year, month: startMonth, day: startDay };
}

function buildSeasonalCountdown(
  cal: BeastCalendarDate,
  startMonth: number,
  startDay: number,
  duration: number,
  label: string,
  id: SurvivalCountdown['id'],
): SurvivalCountdown {
  if (isInSeasonWindow(cal, startMonth, startDay, duration)) {
    const remain = startDay + duration - 1 - cal.day;
    return {
      id,
      label,
      text: remain <= 0 ? '进行中 · 末段' : `进行中 · 剩 ${remain} 天`,
      tone: 'active',
    };
  }

  const next = nextSeasonStart(cal, startMonth, startDay);
  const days = daysBetween(cal, next);
  return {
    id,
    label,
    text: `${days} 天`,
    tone: days <= 7 ? 'soon' : 'normal',
  };
}

function buildInvasionCountdown(cal: BeastCalendarDate): SurvivalCountdown {
  const lastDay = lastDayOfMonth(cal.year, cal.month);
  if (cal.day === lastDay) {
    return { id: 'invasion', label: '野兽入侵', text: '今夜', tone: 'active' };
  }

  const days = lastDay - cal.day;
  return {
    id: 'invasion',
    label: '野兽入侵',
    text: `${days} 天`,
    tone: days <= 3 ? 'soon' : 'normal',
  };
}

/** 按世界书：每月末夜入侵；7/15 与 1/15 起各 15 天极端气候 */
export function getSurvivalEventCountdowns(兽历: string): SurvivalCountdown[] {
  const cal = parse_beast_calendar_date(兽历);
  if (!cal) {
    return EMPTY_COUNTDOWNS;
  }

  return [
    buildInvasionCountdown(cal),
    buildSeasonalCountdown(cal, 7, 15, 15, '夏季雷暴', 'storm'),
    buildSeasonalCountdown(cal, 1, 15, 15, '冬季寒潮', 'winter'),
  ];
}
