import type { CustomOpeningDraft } from '../composables/useCustomOpeningDraft';

const LOCAL_PRESET_KEY = 'status_bar:兽耳娘:custom_opening_draft';

export function has_custom_opening_preset(): boolean {
  try {
    return Boolean(localStorage.getItem(LOCAL_PRESET_KEY));
  } catch {
    return false;
  }
}

export function save_custom_opening_preset(draft: CustomOpeningDraft): void {
  localStorage.setItem(LOCAL_PRESET_KEY, JSON.stringify(draft));
}

export function load_custom_opening_preset(): CustomOpeningDraft | null {
  try {
    const raw = localStorage.getItem(LOCAL_PRESET_KEY);
    if (!raw) {
      return null;
    }
    return JSON.parse(raw) as CustomOpeningDraft;
  } catch {
    return null;
  }
}
